def simulate_dispatch(capacity, day_data, opening_stocks, weights, products):
    stock = dict(opening_stocks)
    order_queue = []
    results = {}
    days = sorted(day_data.keys())

    for day in days:
        for p in products:
            stock[p] += day_data[day][p]['produced']

        for p in products:
            ordered = day_data[day][p]['ordered']
            if ordered > 0:
                order_queue.append([day, ordered, p])

        order_queue.sort(key=lambda x: (x[0], x[1], x[2]))
        remaining_capacity = capacity
        shipped_today = {p: 0 for p in products}

        i = 0
        while i < len(order_queue):
            order = order_queue[i]
            remaining_qty = order[1]
            product = order[2]

            if remaining_qty <= 0:
                order_queue.pop(i)
                continue

            weight = weights[product]
            max_by_stock = stock[product]
            max_by_capacity = int(remaining_capacity / weight)
            units_to_ship = min(remaining_qty, max_by_stock, max_by_capacity)

            if units_to_ship > 0:
                shipped_today[product] += units_to_ship
                stock[product] -= units_to_ship
                order[1] -= units_to_ship
                remaining_capacity -= units_to_ship * weight
                if order[1] == 0:
                    order_queue.pop(i)
                else:
                    i += 1
            else:
                i += 1

        backordered_today = {p: 0 for p in products}
        for order in order_queue:
            backordered_today[order[2]] += order[1]

        results[day] = {'stock': dict(stock), 'backordered': dict(backordered_today), 'shipped': dict(shipped_today)}

    return results

